const {DatabaseSync}=require('node:sqlite');
const db=new DatabaseSync('.codegraph/codegraph.db',{readOnly:true});
function look(fp,name){
  const n=db.prepare('SELECT id,qualified_name,signature FROM nodes WHERE file_path=? AND name=?').get(fp,name);
  const c=db.prepare(\"SELECT DISTINCT s.file_path fp, s.name nm FROM edges e JOIN nodes s ON s.id=e.source WHERE e.target=? AND e.kind='calls'\").all(n.id);
  console.log('=== '+name+' ('+n.qualified_name+' '+n.signature+') distinct callers='+c.length);
  console.log(c.slice(0,15).map(x=>'  '+x.fp+' :: '+x.nm).join('\n'));
}
look('internal/scheduler/parser.go','Next');
look('internal/filter/engine.go','CompileToStatement');
look('internal/filter/engine.go','NewEngine');
" 2>/dev/null
